int fakultet(int n) {
    if (n == 0)
        return 1;                  // basfall
    return n * fakultet(n - 1);    // rekursivt anrop med ett mindre problem
}

long long badFib(int n) {          // O(2^n): räknar samma sak om och om igen
    if (n < 2) return n;
    return badFib(n - 1) + badFib(n - 2);
}

long long fibSub(long long a, long long b, int n) {
    if (n == 0) return a;
    return fibSub(b, a + b, n - 1);    // ett anrop per steg: O(n)
}

long long goodFib(int n) {
    return fibSub(0, 1, n);
}
